import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const PHYS_DISCLOSURE = {
  status: 'partial' as const,
  summary:
    'Quantitative models integrate directly with Anatomy 360’s five live Physiology Lab simulators (Cardiac, Respiratory, Renal, Musculoskeletal, Acid–Base/O₂ Curve). Endocrine kinetic ODE modeling remains explicitly planned until validated constants are cited.',
  missingAssets: ['Validated kinetic ODE constants for the planned Endocrine Feedback simulator'],
};

function makePhysChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  readingKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  simNote: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'human_physiology',
    chapterCode: `E${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['school_foundations', 'secondary_premed', 'medical_foundations', 'clinical_applied', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_gs_4_8', gradeOrYear: 'Grades 7–8', unitOrModule: `Human Organ Systems (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grades X–XII', unitOrModule: `Coordination, Gas Exchange & Homeostasis (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–2', unitOrModule: `Human Physiology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Systems & Quantitative Physiology (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Membrane permeability & active pumps (B3)', 'Organ gross structure (Domain A)'],
    learningObjectives: [
      `Describe the core negative/positive feedback loops, driving gradients, and effectors regulating ${chapterTitle.toLowerCase()}.`,
      `Apply foundational physiological relationships and physical laws governing ${chapterTitle.toLowerCase()} to normal vs stressed states.`,
      `Predict homeostatic compensation and clinical decompensation patterns when primary parameters fail.`,
    ],
    depthExplanations: {
      school_foundations: `${summary} Your body automatically adjusts organ activity every second to keep internal cells supplied with oxygen, nutrients, and balanced fluid levels.`,
      secondary_premed: `${summary} Negative feedback restores homeostasis by opposing deviations from normal physiological set points via nervous or hormonal signals.`,
      medical_foundations: `${mechanisms.join(' ')} Platform integration: ${simNote}`,
      clinical_applied: `Bedside pathophysiology of ${chapterTitle.toLowerCase()} follows direct shifts in driving pressure, conductance, or autonomic compensation: ${clinical}`,
      allied_health: `Vital signs, fluid status, oxygen saturation, and rehabilitation tolerances directly mirror the feedback controls studied in ${chapterTitle.toLowerCase()}.`,
      graduate_research: `Quantitative modeling couples non-linear physiological transfer functions, Hill/Starling/Henderson–Hasselbalch constraints, and autonomic time-delays across integrated organ loops. ${simNote}`,
    },
    keyConcepts: [
      { term: 'Primary Regulatory Principle', definition: summary },
      { term: 'Quantitative / Simulator Link', definition: simNote },
      { term: 'Clinical Decompensation', definition: clinical },
    ],
    keyFacts: [
      simNote,
      'Homeostatic systems exhibit dynamic equilibrium around defended set points rather than rigid static immobility.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Negative feedback weakens biological function.', correction: 'Negative feedback stabilizes internal variables (MAP, PaCO2, pH, glucose) against external disturbance—vital for survival.' },
      { misconception: 'Organs function independently without cross-system feedback.', correction: 'Cardiovascular, respiratory, renal, and autonomic controllers share neural and humoral loops continuously.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} connects physical membrane and fluid laws to whole-organism homeostatic survival. Use Anatomy 360’s Physiology Lab to vary parameters interactively where validated quantitative models exist.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      simNote,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'human_anatomy', relation: 'Spatial organ topology and neurovascular pathways underpin physiological gradients.' },
      { domainId: 'pharmacology', relation: 'Therapeutic drugs target physiological receptors, channels, and feedback checkpoints.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['quantitative_simulation', '2d_diagram', '3d_anatomy'],
    diagram: {
      id: `diag-e${num}`,
      title: `${chapterTitle} — Homeostatic Control Loop`,
      kind: 'pathway',
      caption: summary,
      disclaimer: `Conceptual physiology loop schematic. ${simNote}`,
      nodes: [
        { id: 'n1', label: 'Stimulus & Sensor', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Integrating Law / Centre', sublabel: mechanisms[1]?.slice(0, 62) || simNote.slice(0, 62), tone: 'blue' },
        { id: 'n3', label: 'Effector Restoration', sublabel: mechanisms[2]?.slice(0, 62) || clinical.slice(0, 62), tone: 'emerald' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Afferent sensory / concentration signal' },
        { from: 'n2', to: 'n3', label: 'Efferent autonomic or humoral output restores set point' },
      ],
    },
    assetDisclosure: PHYS_DISCLOSURE,
    activity: {
      title: `Quantitative Reasoning Lab (${chapterTitle})`,
      kind: 'simulation',
      prompt: `Open the Anatomy 360 Physiology Lab or solve the parameter scenario for ${chapterTitle}: ${simNote} Predict the direction of physiological compensation.`,
      keyTakeaway: clinical,
    },
    readingKeys: [readingKey, 'ap_ch1_homeostasis'],
    shortAnswers: [
      { id: `sa-e${num}-1`, prompt: `Trace the sensor, integrating centre, and effector in ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'secondary_premed' },
      { id: `sa-e${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} physiologically.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'medical_foundations' },
      { id: `sa-e${num}-3`, prompt: `Predict how ${chapterTitle} compensates during acute clinical disturbance.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-e${num}-1`,
      title: `Bedside Homeostasis & Compensation Case: ${chapterTitle}`,
      scenario: `A clinical physiology exercise tests how altering driving pressure or receptor feedback alters outputs across ${chapterTitle.toLowerCase()}.`,
      questions: ['Which variable changes first?', 'How does negative feedback buffer the primary perturbation?'],
      workedSolution: `${mechanisms[0]} Applied outcome: ${clinical}`,
      level: 'clinical_applied',
    },
    selfChecks: mcqs,
  };
}

